package com.fixmer.mared.technology.server.setup;
import com.fixmer.genesis.technology.server.remote.*;import com.fixmer.mared.technology.server.remote.ServerAdminPayloads75;
import com.google.gson.*;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.network.PacketDistributor;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Native-screen service. Local OS-owner tools and ServerPlayer-authorized remote requests stay separate. */
public final class DedicatedPanelService75 {
 private static final Gson JSON=new GsonBuilder().setPrettyPrinting().create();private static final AtomicBoolean busy=new AtomicBoolean(),polling=new AtomicBoolean();private static volatile JsonObject local=new JsonObject();private static volatile Map<String,String> remote=Map.of();private static volatile String result="IDLE";private static volatile Path bundle;private static long polled;private static Object connection;private static final Map<UUID,Long> requests=new LinkedHashMap<>();private static JsonObject prefs;
 static{ServerAdminPayloads75.clientSink=DedicatedPanelService75::receive;}
 private DedicatedPanelService75(){}
 public static synchronized JsonObject preferences(){if(prefs==null){prefs=new JsonObject();try{Path p=preferencesPath();if(Files.isRegularFile(p)&&Files.size(p)<32768)prefs=JsonParser.parseString(Files.readString(p)).getAsJsonObject();}catch(Exception ignored){}}return prefs.deepCopy();}
 private static Path preferencesPath(){return Minecraft.getInstance().gameDirectory.toPath().resolve("config/mared/dedicated-panel75.json");}
 public static synchronized void save(JsonObject p){prefs=p.deepCopy();try{Path path=preferencesPath();Files.createDirectories(path.getParent());com.fixmer.genesis.technology.server.firstlaunch.FirstLaunchFiles.write(path,JSON.toJson(p).getBytes(StandardCharsets.UTF_8),true);}catch(Exception ignored){}}
 public static boolean busy(){return busy.get();}public static String result(){return result;}public static Map<String,String> remote(){return Map.copyOf(remote);}public static JsonObject local(){return local.deepCopy();}
 public static boolean hasRemote(){var c=Minecraft.getInstance().getConnection();return c!=null&&c.hasChannel(ServerAdminPayloads75.Request.TYPE.id());}
 public static void request(String action,String label){Minecraft mc=Minecraft.getInstance();if(!hasRemote()){result="NOT_MANAGED";return;}if(connection!=mc.getConnection()){connection=mc.getConnection();requests.clear();remote=Map.of();}UUID id=UUID.randomUUID();requests.entrySet().removeIf(e->System.nanoTime()-e.getValue()>10_000_000_000L);if(requests.size()>=8){result="BUSY";return;}requests.put(id,System.nanoTime());PacketDistributor.sendToServer(new ServerAdminPayloads75.Request(id,action,label));if(!action.equals("PING"))result="SENT";}
 private static void receive(ServerAdminPayloads75.View p){Minecraft mc=Minecraft.getInstance();if(connection!=mc.getConnection()||requests.remove(p.request())==null)return;try{var d=ControlWire73.decode(p.bytes());if(d.containsKey("result")){result=d.get("result");if(d.containsKey("run"))remote=d;}}catch(Exception bad){result="REFUSED";}}
 public static void poll(boolean host,String root){long now=System.nanoTime();if(now-polled<2_000_000_000L)return;polled=now;if(host){if(!root.isBlank()&&polling.compareAndSet(false,true)){Thread task=new Thread(()->{try{Path path=Path.of(root);if(Files.isRegularFile(path.resolve("view75"))){var d=DedicatedAdmin75.open(path).view();JsonObject j=new JsonObject();d.forEach(j::addProperty);long age=System.currentTimeMillis()-Long.parseLong(d.get("updated"));if(age>10000){j.addProperty("phase","OWNER_UNAVAILABLE");}local=j;}else{JsonObject j=new JsonObject();j.addProperty("phase","INITIALIZED");local=j;}}catch(Exception bad){result="OWNER_UNAVAILABLE";}finally{polling.set(false);}},"genesis-panel75-view");task.setDaemon(true);task.start();}}else if(hasRemote())request("PING","r1");}
 static synchronized Path bundle()throws Exception{if(bundle!=null)return bundle;Path parent=Path.of(System.getenv("LOCALAPPDATA"),"Genesis","dedicated-panel75");ServerSetupBundle59.ensureDirectory(parent);Path dir=Files.createTempDirectory(parent,"bundle-");ServerSetupBundle59.privateDirectory(dir);ServerSetupBundle59.unpack(dir,DedicatedPanelService75.class.getResourceAsStream("/genesis/server59/controller.zip"));bundle=dir;return dir;}
 static Path java(){Path path=Path.of(ProcessHandle.current().info().command().orElseThrow());return path.getFileName().toString().equalsIgnoreCase("javaw.exe")?path.resolveSibling("java.exe"):path;}
 public static void host(String operation,String root,String source,String mods,String label){if(operation.equals("run")&&(System.getenv("GENESIS_REMOTE70_ROOT")!=null||System.getenv("GENESIS_FIRST58_ROOT")!=null||System.getenv("GENESIS_PANEL67_ROOT")!=null)){result="START_FROM_TERMINAL";return;}if(!busy.compareAndSet(false,true))return;result="WORKING";
  Thread worker=new Thread(()->{try{if(!System.getProperty("os.name","").toLowerCase(Locale.ROOT).startsWith("windows"))throw new IllegalStateException();Path home=bundle();List<String> args=new ArrayList<>(List.of("-3",home.resolve("tools/dedicated_server75.py").toString(),home.toString(),operation));
   switch(operation){case "init"->{args.add(source);args.add("--java");args.add(java().toString());}case "author"->{args.add(root);args.add(source);args.add(mods);args.add("--label");args.add(label);}case "command"->{args.add(root);args.add(source);args.add("--label");args.add(label);}case "run","status","history"->args.add(root);default->throw new IllegalArgumentException();}
   Process process;try{process=launch("pyw.exe",args,home,root);}catch(java.io.IOException absent){process=launch("py.exe",args,home,root);}
   if(operation.equals("run")){if(process.waitFor(800,java.util.concurrent.TimeUnit.MILLISECONDS)&&process.exitValue()!=0){Path error=home.resolve("panel75-error.log");result=Files.isRegularFile(error)&&Files.size(error)<4096&&Files.readString(error).contains("DEDICATED75_START_FROM_TERMINAL")?"START_FROM_TERMINAL":Files.isRegularFile(error)&&Files.size(error)<4096&&Files.readString(error).contains("DEDICATED77_USE_RECOVERY")?"RECOVERY_REQUIRED":"REFUSED";return;}result="OWNER_STARTED";return;}
   if(!process.waitFor(operation.equals("init")?600:180,java.util.concurrent.TimeUnit.SECONDS)){process.destroy();throw new IllegalStateException();}byte[] bytes=process.getInputStream().readNBytes(65537);if(process.exitValue()!=0||bytes.length>65536)throw new IllegalStateException();String text=new String(bytes,StandardCharsets.UTF_8).trim();JsonElement parsed=JsonParser.parseString(text);if(parsed.isJsonObject()){local=parsed.getAsJsonObject();if(operation.equals("init")){String created=local.get("root").getAsString();synchronized(DedicatedPanelService75.class){JsonObject p=preferences();p.addProperty("root",created);save(p);}}}result=operation.equals("command")?"QUEUED":"DONE";
  }catch(Exception bad){result="REFUSED";}finally{busy.set(false);}},"genesis-panel75-local");worker.setDaemon(true);worker.start();
 }
 private static Process launch(String exe,List<String> args,Path home,String root)throws Exception{List<String> cmd=new ArrayList<>();cmd.add(exe);cmd.addAll(args);ProcessBuilder builder=new ProcessBuilder(cmd).directory(home.toFile());builder.environment().put("PYTHONUTF8","1");builder.environment().put("PYTHONIOENCODING","utf-8");Path log=home.resolve("panel75-error.log");builder.redirectError(log.toFile());if(args.contains("run"))builder.redirectOutput(home.resolve("panel75-owner.log").toFile());return builder.start();}
}
